import channels_graphql_ws
import graphene
from graphql import GraphQLError
from .models import SupportTicket
from .types import TicketMessageType

class SupportTicketMessageSubscription(channels_graphql_ws.Subscription):
    message = graphene.Field(TicketMessageType)

    class Arguments:
        ticket_id = graphene.Int(required=True)

    @classmethod
    def subscribe(cls, root, info, ticket_id):
        user = info.context.user
        if not user.is_authenticated:
            raise GraphQLError("User must be logged in")

        ticket = SupportTicket.objects.filter(id=ticket_id).first()
        if not ticket or (ticket.customer != user and ticket.assigned_agent != user):
            raise GraphQLError("Ticket not found or permission denied")

        group_name = f"support_ticket_chat_{ticket_id}"
        return [group_name]

    @classmethod
    def publish(cls, payload, info, ticket_id):
        return cls(message=payload["ticket_message"])
